public class BonDepenseGenerator : BasePdfGenerator
{
  public byte[] Generate(DepenseDto depense)
  {
    var document = Document.Create(container =>
    {
      container.Page(page =>
      {
        page.Size(PageSizes.A4);
        page.Margin(2, Unit.Centimetre);
        page.DefaultTextStyle(x => x.FontSize(11).FontFamily("Arial"));

        // Header
        page.Header().Row(row =>
        {
          row.RelativeItem().Column(column =>
          {
            column.Item().Text("BON DE DÉPENSE").FontSize(20).Bold();
            column.Item().Text($"N° {depense.NumeroBon}").FontSize(14);
          });
          row.ConstantItem(80).Image(GenerateQRCode(depense.Id));
        });

        // Content
        page.Content().Column(column =>
        {
          column.Spacing(10);

          // Section info
          column.Item().Row(row =>
          {
            row.RelativeItem().Text($"Section: {depense.SectionNom}").Bold();
            row.RelativeItem().AlignRight().Text($"Date: {depense.DateDepense:dd/MM/yyyy}");
          });

          // Details
          column.Item().Border(1).Padding(10).Column(col =>
          {
            col.Item().Text($"Libellé: {depense.Libelle}");
            col.Item().Text($"Montant: {depense.Montant:N0} FCFA").FontSize(16).Bold();
            col.Item().Text($"Montant en lettres: {ConvertToWords(depense.Montant)}");
            col.Item().Text($"Bénéficiaire: {depense.Beneficiaire}");
            col.Item().Text($"Catégorie: {depense.Categorie}");
          });

          // Signatures
          column.Item().PaddingTop(30).Row(row =>
          {
            row.RelativeItem().Column(col =>
            {
              col.Item().Text("Demandeur").Bold();
              if (!string.IsNullOrEmpty(depense.Signature1Path))
                col.Item().Image(depense.Signature1Path).FitWidth();
              col.Item().PaddingTop(20).LineHorizontal(1);
            });

            row.RelativeItem().Column(col =>
            {
              col.Item().Text("Validateur").Bold();
              if (!string.IsNullOrEmpty(depense.Signature2Path))
                col.Item().Image(depense.Signature2Path).FitWidth();
              col.Item().PaddingTop(20).LineHorizontal(1);
            });
          });
        });

        // Footer
        page.Footer().AlignCenter().Text(text =>
        {
          text.Span($"Généré le {DateTime.Now:dd/MM/yyyy HH:mm}").FontSize(8);
          text.Span(" - Page ").FontSize(8);
          text.CurrentPageNumber().FontSize(8);
        });
      });
    });

    return document.GeneratePdf();
  }
}
